409	    /**
410	     * Validate and normalize the owner's address fields in place, preferring the structured
411	     * form over the flat 'address' for backward compatibility.
412	     *
413	     * <p>When a non-blank {@code addressLine1} is supplied it is the structured form: both
414	     * {@code addressLine1} and (when present) {@code addressLine2} are normalized and stored
415	     * back, and {@code address} is set to the composed value — the normalized addressLine1,
416	     * with a single space and the normalized addressLine2 appended when addressLine2 is present.
417	     * Otherwise the flat {@code address} is normalized in place and the structured lines are
418	     * cleared. Returns {@code false} when no address is supplied in either form (both the
419	     * structured addressLine1 and the flat address are blank once normalized), so the caller
420	     * can reject with 400.
421	     */
422	    private boolean normalizeAddresses(OwnerFieldsDto ownerFieldsDto) {
423	        String rawLine1 = ownerFieldsDto.getAddressLine1();
424	        if (rawLine1 != null && !rawLine1.isBlank()) {
425	            String line1 = normalizeAddress(rawLine1);
426	            if (line1.isBlank()) {
427	                return false;
428	            }
429	            ownerFieldsDto.setAddressLine1(line1);
430	            String rawLine2 = ownerFieldsDto.getAddressLine2();
431	            String composed = line1;
432	            if (rawLine2 != null && !rawLine2.isBlank()) {
433	                String line2 = normalizeAddress(rawLine2);
434	                ownerFieldsDto.setAddressLine2(line2);
435	                composed = line1 + " " + line2;
436	            }
437	            else {
438	                ownerFieldsDto.setAddressLine2(null);
439	            }
440	            ownerFieldsDto.setAddress(composed);
441	            return true;
442	        }
443	        // No structured address: fall back to the flat 'address' input.
444	        String canonicalAddress = normalizeAddress(ownerFieldsDto.getAddress());
445	        if (canonicalAddress.isBlank()) {
446	            return false;
447	        }
448	        ownerFieldsDto.setAddress(canonicalAddress);
449	        ownerFieldsDto.setAddressLine1(null);
450	        ownerFieldsDto.setAddressLine2(null);
451	        return true;
452	    }
