479	    /**
480	     * Normalize a telephone number to E.164 form.
481	     *
482	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
483	     * explicit leading {@code '+'} and country code it is kept; otherwise the
484	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
485	     * dropped from the national digits. The result must contain 8 to 15 digits
486	     * after the {@code '+'}, and — for a recognised country calling code — exactly
487	     * the national-number length that code mandates ({@code '+61'} => 9 national
488	     * digits, {@code '+1'} => 10).
489	     *
490	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
491	     *         the input is absent or cannot form a valid E.164 number.
492	     */
493	    private static String toE164(String raw) {
494	        if (raw == null) {
495	            return null;
496	        }
497	        String trimmed = raw.trim();
498	        boolean hasCountryCode = trimmed.startsWith("+");
499	        // Strip spaces, dashes and brackets.
500	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
501	        String digits;
502	        if (hasCountryCode) {
503	            // Keep the explicit country code; drop the leading '+' for validation.
504	            digits = stripped.substring(1);
505	        } else {
506	            // No country code: assume '+61' and drop a single leading '0'.
507	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
508	            digits = "61" + national;
509	        }
510	        if (!digits.matches("\\d{8,15}")) {
511	            return null;
512	        }
513	        // For a recognised country calling code, enforce the exact national-number length it
514	        // mandates (e.g. '+61' => 9 national digits, '+1' => 10). Longer codes win so a '+61'
515	        // number is not mistaken for a '+6...' one. Unknown codes keep the generic 8-15 rule.
516	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet().stream()
517	                .sorted((a, b) -> b.length() - a.length()).toList()) {
518	            if (digits.startsWith(countryCode)) {
519	                int nationalLength = digits.length() - countryCode.length();
520	                if (nationalLength != NATIONAL_NUMBER_LENGTHS.get(countryCode)) {
521	                    return null;
522	                }
523	                break;
524	            }
525	        }
526	        return "+" + digits;
527	    }
