543	    /**
544	     * Count the existing owners in the same household as the given owner, i.e. those sharing its
545	     * computed householdId (derived from the normalized last name and postcode). Used, together
546	     * with the owner being created, to derive the household size recorded on the owner.
547	     */
548	    private int countHouseholdMembers(Owner owner) {
549	        String householdId = ownerMapper.householdId(owner);
550	        return (int) this.clinicService.findAllOwners().stream()
551	            .filter(existing -> householdId.equals(ownerMapper.householdId(existing)))
552	            .count();
553	    }
