574	    /**
575	     * Find an existing owner that the given (not-yet-created) owner is a possible (soft) duplicate
576	     * of: one whose identity key differs (so it is not a hard duplicate) yet whose last name shares
577	     * the same Soundex code and whose postcode is the same. Owners without a postcode never match
578	     * (the postcode must be shared) and deleted owners are ignored. When several existing owners
579	     * match, the one with the lowest id is returned so the result is deterministic. Returns
580	     * {@code null} when there is no such match.
581	     */
582	    private Owner findPossibleDuplicate(Owner candidate) {
583	        if (candidate.getPostcode() == null) {
584	            return null;
585	        }
586	        String candidateKey = ownerMapper.identityKey(candidate);
587	        String candidateSoundex = Soundex.of(candidate.getLastName());
588	        return this.clinicService.findAllOwners().stream()
589	            .filter(existing -> !existing.isDeleted())
590	            .filter(existing -> !candidateKey.equals(ownerMapper.identityKey(existing)))
591	            .filter(existing -> candidate.getPostcode().equals(existing.getPostcode())
592	                && candidateSoundex.equals(Soundex.of(existing.getLastName())))
593	            .min(java.util.Comparator.comparing(Owner::getId))
594	            .orElse(null);
595	    }
