597	    /**
598	     * The owner's current primary identifier, as carried by structured audit events: the
599	     * unified memberId.
600	     */
601	    private String primaryIdentifier(Owner owner) {
602	        return owner.getMemberId();
603	    }
604	
605	    /**
606	     * Build the owner's unified memberId, formatted {@code '<REGION><FY><HASH8><CHK>'}.
607	     *
608	     * <p>{@code REGION} is the region derived from the owner's postcode (see
609	     * {@link #deriveRegion}). {@code FY} is the two-digit fiscal year (starting 1 July) of the
610	     * business-day-adjusted registration date. {@code HASH8} is the first 8 upper-case hex
611	     * characters of the SHA-256 of the normalized telephone concatenated with the last name.
612	     * {@code CHK} is a single Luhn check digit computed over the digits of
613	     * {@code '<REGION><FY><HASH8>'} (e.g. {@code 'NSW271A2B3C4D5'}).
614	     *
615	     * <p>When the computed memberId collides with an existing owner's memberId, it is
616	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more
617	     * that makes it unique.
618	     */
619	    private String memberId(Owner owner) {
620	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
621	        String fy = String.format("%02d", fiscalYearTwoDigits(owner.getRegistrationDate()));
622	        String hash8 = sha256HexUpper(owner.getTelephone() + owner.getLastName(), 8);
623	        String base = region + fy + hash8;
624	        String memberId = base + luhn(base);
625	        Set<String> existing = this.clinicService.findAllOwners().stream()
626	            .map(Owner::getMemberId)
627	            .filter(java.util.Objects::nonNull)
628	            .collect(Collectors.toSet());
629	        if (!existing.contains(memberId)) {
630	            return memberId;
631	        }
632	        int n = 2;
633	        while (existing.contains(memberId + "-" + n)) {
634	            n++;
635	        }
636	        return memberId + "-" + n;
637	    }
638	
639	    /**
640	     * The two-digit fiscal year (starting 1 July) of the given date: the last two digits of the
641	     * calendar year in which the fiscal year ends. Dates on or after 1 July belong to the fiscal
642	     * year ending the following calendar year (e.g. 2026-08-10 -&gt; 27); earlier dates belong to
643	     * the fiscal year ending in the same calendar year (e.g. 2026-03-01 -&gt; 26).
644	     */
645	    private static int fiscalYearTwoDigits(LocalDate date) {
646	        int endYear = date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
647	        return endYear % 100;
648	    }
649	
650	    /**
651	     * A single Luhn check digit (0-9) computed over the digit characters contained in
652	     * {@code value}; non-digit characters are ignored.
653	     */
654	    private static int luhn(String value) {
655	        int sum = 0;
656	        boolean dbl = true;
657	        for (int i = value.length() - 1; i >= 0; i--) {
658	            char c = value.charAt(i);
659	            if (c < '0' || c > '9') {
660	                continue;
661	            }
662	            int d = c - '0';
663	            if (dbl) {
664	                d *= 2;
665	                if (d > 9) {
666	                    d -= 9;
667	                }
668	            }
669	            sum += d;
670	            dbl = !dbl;
671	        }
672	        return (10 - (sum % 10)) % 10;
673	    }
674	
675	    /**
676	     * Derive the owner's region, preferring the postcode. The postcode is matched against
677	     * each region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); only when
678	     * it is absent or in no known range does this fall back to the fixed city-to-region table
679	     * (see {@link OwnerMapper#CITY_REGION}), and finally {@code 'UNKNOWN'}.
680	     */
681	    private static String deriveRegion(String postcode, String city) {
682	        if (postcode != null && postcode.matches("\\d{4}")) {
683	            int value = Integer.parseInt(postcode);
684	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
685	                int[] range = entry.getValue();
686	                if (value >= range[0] && value <= range[1]) {
687	                    return entry.getKey();
688	                }
689	            }
690	        }
691	        return OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
692	    }
693	
694	    /**
695	     * The first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
696	     * bytes of {@code value}.
697	     */
698	    private static String sha256HexUpper(String value, int length) {
699	        try {
700	            byte[] digest = MessageDigest.getInstance("SHA-256")
701	                .digest(value.getBytes(StandardCharsets.UTF_8));
702	            StringBuilder sb = new StringBuilder(digest.length * 2);
703	            for (byte b : digest) {
704	                sb.append(String.format("%02X", b));
705	            }
706	            return sb.substring(0, length);
707	        }
708	        catch (NoSuchAlgorithmException e) {
709	            throw new IllegalStateException(e);
710	        }
711	    }
712	
713	    /**
714	     * Count the existing owners located in the given city, compared case-insensitively.
715	     * Used to enforce the per-city capacity limit and capacity warning.
716	     */
717	    private int countOwnersInCity(String city) {
718	        return (int) this.clinicService.findAllOwners().stream()
719	            .filter(existing -> existing.getCity() != null
720	                && existing.getCity().equalsIgnoreCase(city))
721	            .count();
722	    }
723	
724	    /**
725	     * Count the existing owners whose registration date is the given (adjusted business) date.
726	     * Used to enforce the per-day sign-up limit.
727	     */
728	    private int countOwnersRegisteredOn(LocalDate date) {
729	        return (int) this.clinicService.findAllOwners().stream()
730	            .filter(existing -> date.equals(existing.getRegistrationDate()))
731	            .count();
732	    }
733	
734	    /** Fixed public holidays the business-day roll skips. */
735	    private static final Set<LocalDate> HOLIDAYS = Set.of(
736	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
737	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
738	        LocalDate.parse("2026-12-28"));
739	
740	    /**
741	     * Roll a registration date forward onto a business day: a Saturday, Sunday, or listed
742	     * public holiday is moved forward to the next non-holiday weekday; a plain weekday is
743	     * returned unchanged.
744	     */
745	    private static LocalDate toBusinessDay(LocalDate date) {
746	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
747	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
748	            || HOLIDAYS.contains(date)) {
749	            date = date.plusDays(1);
750	        }
751	        return date;
752	    }
753	
754	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
755	    @Override
756	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
757	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
758	        if (currentOwner == null) {
759	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
760	        }
761	        if (!normalizeEmail(ownerFieldsDto)) {
762	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
763	        }
764	        if (!normalizePostcode(ownerFieldsDto)) {
765	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
766	        }
767	        if (!normalizeAddresses(ownerFieldsDto)) {
768	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
769	        }
770	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
771	        if (normalizedTelephone == null) {
772	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
773	        }
774	        currentOwner.setAddress(ownerFieldsDto.getAddress());
775	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
776	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
777	        currentOwner.setCity(ownerFieldsDto.getCity());
778	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
779	        currentOwner.setLastName(ownerFieldsDto.getLastName());
780	        currentOwner.setTelephone(normalizedTelephone);
781	        currentOwner.setEmail(ownerFieldsDto.getEmail());
782	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
783	        this.clinicService.saveOwner(currentOwner);
784	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
785	    }
786	
787	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
788	    @Transactional
789	    @Override
790	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
791	        Owner owner = this.clinicService.findOwnerById(ownerId);
792	        if (owner == null) {
793	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
794	        }
795	        // Soft-delete: flag the owner deleted and retain the record so it can still be
796	        // read back (with 'deleted' true) and is ignored by later duplicate/identity checks.
797	        owner.setDeleted(true);
798	        this.clinicService.saveOwner(owner);
799	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
800	    }
801	
802	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
803	    @Override
804	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
805	        Owner owner = this.clinicService.findOwnerById(ownerId);
806	        if (owner == null) {
807	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
808	        }
809	        HttpHeaders headers = new HttpHeaders();
810	        Pet pet = petMapper.toPet(petFieldsDto);
811	        owner.setId(ownerId);
812	        pet.setOwner(owner);
813	        pet.getType().setName(null);
814	        this.clinicService.savePet(pet);
815	        PetDto petDto = petMapper.toPetDto(pet);
816	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
817	            .buildAndExpand(pet.getId()).toUri());
818	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
819	    }
820	
821	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
822	    @Override
823	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
824	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
825	        if (currentOwner != null) {
826	            Pet currentPet = this.clinicService.findPetById(petId);
827	            if (currentPet != null) {
828	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
829	                currentPet.setName(petFieldsDto.getName());
830	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
831	                this.clinicService.savePet(currentPet);
832	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
833	            }
834	        }
835	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
